<?php

namespace gbaneBundle\Repository;

/**
 * ReglesRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class ReglesRepository extends \Doctrine\ORM\EntityRepository
{
    public function findByregles($grade,$fonctionassimilees,$anciennetedge,$anciennetegrade,$agent=null)
    {
        
      $qb = $this->getEntityManager()->createQueryBuilder()
      ->select('r')
              ->from('gbaneBundle:Regles', 'r')
              ->join('r.FonctionAssimilees','f')
              ->where('1=1')
              ;
      if($grade>0)
      {
          $qb=$qb->andWhere('r.grade = :grade')
                  ->setParameter('grade', $grade);
      }
      if($fonctionassimilees>0 && $agent==null)
      {
         $qb=$qb->andWhere('r.FonctionAssimilees = :fonctionassimilees')
               ->setParameter('fonctionassimilees', $fonctionassimilees);
      }
      if($anciennetedge>0 && $agent!=null)
      {
          $qb=$qb->andWhere(':anciennetedge >= r.ancienneteDge')
                  ->setParameter('anciennetedge', $anciennetedge);
      }
      if($anciennetegrade>0 && $agent!=null)
      {
          $qb=$qb->andWhere(':anciennetegrade >= r.ancienneteGrade')
                  ->setParameter('anciennetegrade', $anciennetegrade);
      }
      if($anciennetedge>0 && $agent==null)
      {
          $qb=$qb->andWhere('r.ancienneteDge >=:anciennetedge')
                  ->setParameter('anciennetedge', $anciennetedge);
      }
      if($anciennetegrade>0 && $agent==null)
      {
          $qb=$qb->andWhere('r.ancienneteGrade >=:anciennetegrade')
                  ->setParameter('anciennetegrade', $anciennetegrade);
      }
      
      $qb= $qb->orderBy('f.poidsFonctAss','ASC');
              return $qb->getQuery()->getResult();
      
    }
}

